Let $\mathcal{A}, \mathcal{B}$ be finite sets, let $P_A \in \Delta(\mathcal{A})$ and $P_B \in \Delta(\mathcal{B})$. For all $a \in \mathcal{A}$ and $b \in \mathcal{B}$, let $G_a = (\mathcal{V}_a, \mathcal{E}_a, P_{V_a})$ and $G_b = (\mathcal{V}_b, \mathcal{E}_b, P_{V_b})$ be probabilistic graphs. Then 
    \begin{align}
        \left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\right) \wedge \left(\bigsqcup_{b \in \mathcal{B}}^{P_B} G_b\right) = \bigsqcup_{(a,b) \in \mathcal{A} \times \mathcal{B}}^{P_AP_B} G_a \wedge G_b.
    \end{align}

Let $G = (\mathcal{V}, \mathcal{E}, P_V)$ and $\mathcal{S} \subset \mathcal{V}$, then 
        \begin{align}
            H_\chi(G) - 1 - (1-P_V(\mathcal{S}))\log|\mathcal{V}| \leq H_\chi(G[\mathcal{S}]) \leq\frac{H_\chi(G)}{P_V(\mathcal{S})}.
        \end{align}

If $P_A \in \Delta_k(\mathcal{A})$ for some $k \in \mathbb{N}^\star$ then
    \begin{equation}
        \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\right) = \frac{1}{k}\overline{H}\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge k P_A(a)}\right).
    \end{equation}

Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be any sequence such that $T_{\overline{a}^n} \rightarrow P_A$ when $n \rightarrow \infty$. Then we have
    \begin{equation}
        \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \right) = \lim_{n \rightarrow \infty} \frac{1}{n}H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right).
    \end{equation}

Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be a sequence such that $T_{\overline{a}^n} \rightarrow P_A \in \Delta(\mathcal{A})$ when $n \rightarrow \infty$, let $\beta \in (0,1)$ and $P'_A, P''_A \in \Delta(\mathcal{A})$ such that
    \begin{align}
        P_A = \beta P'_A + (1-\beta)P''_A.
    \end{align}
    Then there exists a sequence $(b_n)_{n \in \mathbb{N}^\star} \in \lbrace 0, 1 \rbrace^{\mathbb{N}^\star}$ such that the two extracted sequences $a' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 0}}$ and $a'' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 1}}$ satisfy
    \begin{align}
        & T_{b^n} \underset{n \rightarrow \infty}{\rightarrow} (\beta, 1-\beta), & & \\
        & T_{a'^n} \underset{n \rightarrow \infty}{\rightarrow} P'_A, & & T_{a''^n} \underset{n \rightarrow \infty}{\rightarrow} P''_A.
    \end{align}

Let $\mathcal{A}$ be a finite set, and $\gamma : \Delta(\mathcal{A}) \rightarrow \mathbb{R}$ be a convex function. Then the following holds:
    \begin{align}
        & \exists P_A \in \mathrm{int}(\Delta(\mathcal{A})), \, \gamma(P_A) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \gamma(\mathds{1}_a) \\
        \Longleftrightarrow \;\; & \forall P_A \in \Delta(\mathcal{A}), \, \gamma(P_A) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \gamma(\mathds{1}_a) 
    \end{align}
    where $\mathrm{int}(\Delta(\mathcal{A}))$ is the interior of $\Delta(\mathcal{A})$ (i.e. the full-support distributions on $\mathcal{A}$).

Let $P_A \in \Delta(\mathcal{A})$ with full-support, then the following equivalence holds
    \begin{align}
        & \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\right) = \sum_{a \in \mathcal{A}} P_A(a) \overline{H}(G_a)  \\
        \Longleftrightarrow \;\; & \overline{H}\left(\bigwedge_{a \in \mathcal{A}} G_a\right) = \sum_{a \in \mathcal{A}} \overline{H}(G_a). 
    \end{align}

When $(G_a)_{a \in \mathcal{A}}$ is a family of perfect probabilistic graphs, the following single-letter characterizations hold:
    \begin{align}
        & \overline{H}\left(\bigwedge_{a \in \mathcal{A}} G_a \right) = \sum_{a \in \mathcal{A}} \overline{H}(G_a) = \sum_{a \in \mathcal{A}} H_\kappa(G_a), \\
        &  \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \right) = \sum_{a \in \mathcal{A}} P_A(a) \overline{H}(G_a) = \sum_{a \in \mathcal{A}} P_A(a) H_\kappa(G_a).
    \end{align}
